  'graphics/rect': {
    description: 'Create an immutable rectangle graphic for `self.graph`.',
    params: [['options', 'Positive `width` and `height` in local pixels. `color` defaults to white. `pivot` defaults to `"center"` and also accepts `"top-left"`.']],
    example: 'local box = rect {width = 32, height = 32, color = BLUE}',
    related: ['circle', 'draw_rect'],
  },
  'graphics/circle': {
    description: 'Create an immutable circle graphic with a center pivot for `self.graph`.',
    params: [['options', 'A positive `radius` in local pixels. `color` defaults to white.']],
    example: 'self.graph = circle {radius = 20, color = ORANGE}',
    related: ['rect', 'draw_circle'],
  },
  'graphics/region': {
    description: 'Create an immutable, shareable clip for a process graph and immediate drawing. It intersects the window and camera viewport. Set `self.region = nil` to clear it.',
    params: [['options', 'Four required fields. `x` and `y` are logical screen coordinates in the C `int` range. `width` and `height` are positive integers up to `INT_MAX`.']],
    example: 'self.region = region {x = 40, y = 60, width = 300, height = 240}',
    related: ['scroll'],
  },
  'graphics/scroll': {
    description: 'Set an absolute drawing offset by assigning the descriptor to `self.scroll`. The renderer subtracts it from this process’s graph and immediate drawing. The screen-space clip stays fixed. Set `self.scroll = nil` to reset the offset.',
    params: [['x', 'Horizontal offset.'], ['y', 'Vertical offset. Both values must be finite with magnitude at most `FLT_MAX / 16`.']],
    example: 'self.scroll = scroll(10, 0)',
    related: ['region', 'camera_move'],
  },
  'graphics/animation': {
    description: 'Create a reusable animation for `self.graph`. A process plays it on the simulation clock. Pass a library explicitly or use the scheduled process’s `self.file`.',
    params: [['library?', 'An atlas for named sequences. An atlas, FPG, or FPG manifest for a list of IDs.'],
      ['name', 'A named atlas sequence. It keeps the imported frame durations and direction. Its options table accepts only `loop`.'],
      ['ids', 'A list of sprite IDs. Its options table accepts `loop` and `fps`. For a custom list, `fps` defaults to 8 and ranges from 1/3600 to 1000.'],
      ['loop?', 'Defaults to true for both options tables. Use false to hold the last frame after playback.']],
    example: 'self.file = hero\nself.graph = animation("walk", {loop = false})\nlocal run = animation(hero, {1, 2, 3}, {fps = 12})',
    related: ['graph', 'animation_elapsed', 'animation_finished'],
  },
  'graphics/animation_elapsed': {
    description: 'Read playback time in milliseconds, or `nil` when there is no active animation. The query leaves the clock as it was.',
    params: [['process?', 'A live process handle. Omit the argument when calling from the scheduled process coroutine to read its playback time.']],
    example: 'local ms = animation_elapsed() -- Inside a scheduled process.\nlocal other_ms = animation_elapsed(worker)',
    related: ['animation'],
  },
  'graphics/animation_finished': {
    description: 'Return true when a non-looping animation reaches its full duration, including the final frame. In all other states, return false. A completed animation holds its last frame until the process changes or resets its graph.',
    params: [['handle?', 'A live process handle. Omit it when calling from the scheduled process coroutine. The method form is `handle:animation_finished()`.']],
    example: 'self.graph = animation("explosion", {loop = false})\nwhile not animation_finished() do\n  frame()\nend',
    related: ['animation', 'animation_elapsed'],
  },
  'graphics/graph': {
    description: 'Select a static graphic for `self.graph`. Pass the library explicitly or use `self.file` inside a process. `library:graph(selector)` makes the same explicit selection. Missing sprites and invalid selectors raise errors.',
    params: [['selector', 'A positive integer ID or, for atlases, an exact case-sensitive sprite name. Digit strings are names.']],
    example: '-- With the Aseprite example atlas loaded as sheet\nself.file = sheet\nself.graph = graph("one")',
    related: ['animation', 'draw_sprite'],
  },

