  'world/world_collision': {
    description: 'Return the first overlapping obstacle ID, or nil. The contextual form uses the scheduled process and its `world` field.',
    params: [['world, process', 'Pass both for an explicit query, including from outside a running process.'],
      ['options?', 'A table with optional `x` and `y` position overrides. The query leaves the process position unchanged.']],
    example: 'local id = world_collision()\nlocal ahead = world_collision {x = self.x + 10}\nlocal explicit = world_collision(world, player, {x = 120})',
    related: ['world_overlap', 'world_move'],
  },
  'world/world_move': {
    description: 'Move a process through a static world using its collider. With two arguments, use the running process and its `world` field.',
    params: [['world, process', 'Pass both before the deltas for explicit movement.'],
      ['dx', 'Horizontal delta.'], ['dy', 'Vertical delta.']],
    example: 'local result = world_move(4, 0)\nlocal explicit = world_move(world, player, 4, 0)',
    related: ['world_create'],
  },

