  'platform/rand': {
    description: 'Return a pseudorandom integer between two inclusive bounds. Use it to roll a die or pick a loot table entry.',
    signatures: ['mv.rand(min, max)', 'rand(min, max) -- after mv.import_globals()'],
    params: [
      ['min', 'Required. The lowest value, as a Lua number that can be represented exactly as a Lua integer.'],
      ['max', 'Required. The highest value, with the same type as `min` and a value of at least `min`.'],
    ],
    returns: 'One Lua integer from `min` through `max`. A wrong argument count, an invalid bound, or `min > max` raises a Lua error.',
    exampleSetup: 'With the Malvado SDK installed, save this program as `roll.lua`. From that directory, run `malvado run --headless roll.lua`.',
    example: `local mv = require("malvado")

print("Dice roll: " .. mv.rand(1, 6))`,
    exampleResult: 'The program prints `Dice roll:` followed by an integer from 1 to 6, then exits. Try `mv.rand(6, 6)` to see what happens when both bounds are equal.',
    notes: 'Calls to `rand` and `math.random` advance the same Lua generator. An invalid call leaves the generator state unchanged. See [pseudorandom numbers](../../../../concepts/lua-processes/#pseudorandom-numbers) for repeatable sequences.',
    related: ['rand_seed'],
  },
  'platform/rand_seed': {
    description: 'Call `rand_seed()` to ask Lua to generate a fresh seed, or `rand_seed(seed)` to set an explicit seed. Both forms return no values. Lua 5.4 gives the shared generator a weak initial seed at startup, so ordinary gameplay needs neither call. Use this generator for gameplay and keep it out of cryptographic uses. You can also call `math.randomseed` directly.',
    params: [['seed', 'One Lua integer, including zero or a negative integer. Omit the argument for automatic reseeding. Explicit `nil`, other types and extra arguments raise an error before the generator state changes.']],
    example: 'rand_seed()\n\nrand_seed(12345)\nlocal damage = rand(1, 6)',
    related: ['rand'],
  },

